impl PotentialGrade {
    const ALL: [Self; 5] = [
        Self::VeryLow,
        Self::Low,
        Self::Normal,
        Self::High,
        Self::VeryHigh,
    ];

    fn label(self) -> &'static str {
        match self {
            Self::VeryLow => "Very Low",
            Self::Low => "Low",
            Self::Normal => "Normal",
            Self::High => "High",
            Self::VeryHigh => "Very High",
        }
    }

    fn raw_value(self) -> u16 {
        match self {
            Self::VeryLow => 1,
            Self::Low => 30,
            Self::Normal => 50,
            Self::High => 70,
            Self::VeryHigh => 100,
        }
    }

    fn from_raw(raw: u16) -> Self {
        match raw {
            0..=20 => Self::VeryLow,
            21..=40 => Self::Low,
            41..=60 => Self::Normal,
            61..=80 => Self::High,
            _ => Self::VeryHigh,
        }
    }
}

