fn first_editable_player_communication_region(primary_region: Option<usize>) -> usize {
    COMMUNICATION_REGIONS
        .iter()
        .map(|(region_id, _)| *region_id)
        .find(|region_id| Some(*region_id) != primary_region)
        .unwrap_or(0)
}

